'use strict';

// VARIABLES //

// Shift mask: 0x3f => 00000000000000000000000000111111
var MAX_SHIFT = 63 >>> 0;


// MAIN //

/**
* Performs bitwise shift to the right on a 64-bit unsigned integer and assigns results to a provided output array.
*
* @param {uinteger32} ah - high 32-bit word of the 64-bit unsigned integer
* @param {uinteger32} al - low 32-bit word of the 64-bit unsigned integer
* @param {uinteger32} shift - number of bits to shift (0-63)
* @param {Collection} out - output array
* @param {integer} stride - stride length
* @param {NonNegativeInteger} offset - starting index
* @returns {Collection} output array
*
* @example
* var Uint32Array = require( '@stdlib/array/uint32' );
*
* var out = assign( 2, 4, 1, new Uint32Array( 2 ), 1, 0 );
* // returns <Uint32Array>[ 1, 2 ]
*/
function assign( ah, al, shift, out, stride, offset ) {
	ah >>>= 0;
	al >>>= 0;
	shift &= MAX_SHIFT;

	if ( shift === 0 ) {
		out[ offset ] = ah >>> 0;
		out[ offset + stride ] = al >>> 0;
	} else if ( shift < 32 ) {
		out[ offset ] = ah >>> shift;
		out[ offset + stride ] = ( ( al >>> shift ) | ( ah << ( 32 - shift ) ) ) >>> 0; // eslint-disable-line max-len
	} else {
		out[ offset ] = 0;
		out[ offset + stride ] = ah >>> ( shift - 32 );
	}
	return out;
}


// EXPORTS //

module.exports = assign;
